import 'package:flutter/material.dart';import '../home/home_page.dart';import '../lists/lists_page.dart';import '../goals/goals_page.dart';import '../calendar/calendar_page.dart';import '../settings/settings_page.dart';import '../capture/quick_capture.dart';
class AppShell extends StatefulWidget{const AppShell({super.key});@override State<AppShell>createState()=>_AppShellState();}
class _AppShellState extends State<AppShell>{int index=0;final pages=const[HomePage(),ListsPage(),GoalsPage(),CalendarPage(),SettingsPage()];@override Widget build(BuildContext context)=>PopScope(canPop:false,onPopInvokedWithResult:(didPop,result){if(!didPop&&index!=0)setState(()=>index=0);},child:Scaffold(body:IndexedStack(index:index,children:pages),floatingActionButton:index==4?null:FloatingActionButton.small(onPressed:()=>showQuickCapture(context),child:const Icon(Icons.add)),floatingActionButtonLocation:FloatingActionButtonLocation.endFloat,bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'ホーム'),NavigationDestination(icon:Icon(Icons.checklist),label:'リスト'),NavigationDestination(icon:Icon(Icons.flag_outlined),label:'目標'),NavigationDestination(icon:Icon(Icons.calendar_month_outlined),label:'予定'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'設定')])));}
